#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_series_covers_the_dense_grid_in_order() {
        assert_eq!(ARM_WORDS.len(), 12);
        for (_, _, _, pts) in ARM_WORDS {
            assert_eq!(pts.len(), 44);
            assert!(pts.windows(2).all(|w| w[0].0 < w[1].0));
        }
    }
}
